#!/usr/bin/env bash
set -Eeuo pipefail

if [[ ${EUID:-$(id -u)} -ne 0 ]]; then
  echo 'Запустите установщик от root.' >&2
  exit 1
fi

MODEL='qwen3-vl:2b-instruct'
WHEEL='/tmp/auto_photo_ingest-0.4.0-py3-none-any.whl'
EXPECTED_SHA='f9768c842fd96139a66d0cf71a38805fcdfe91fdea05e33657552e5c32485c22'

echo '[1/7] Останавливаю фоновую обработку на время обновления'
systemctl stop auto-photo-ingest.timer 2>/dev/null || true
systemctl stop auto-photo-ingest.service 2>/dev/null || true

echo '[2/7] Добавляю 4 ГБ swap, если swap отсутствует'
if [[ -z "$(swapon --show --noheadings 2>/dev/null)" ]]; then
  if [[ -e /swapfile ]]; then
    if ! file -b /swapfile | grep -qi 'swap file'; then
      echo '/swapfile уже существует и не является swap; остановка для безопасности.' >&2
      exit 1
    fi
  else
    fallocate -l 4G /swapfile || dd if=/dev/zero of=/swapfile bs=1M count=4096 status=progress
  fi
  chmod 600 /swapfile
  mkswap /swapfile >/dev/null
  swapon /swapfile
  grep -qE '^/swapfile[[:space:]]' /etc/fstab || echo '/swapfile none swap sw 0 0' >> /etc/fstab
fi

echo '[3/7] Устанавливаю/обновляю Ollama из официального установщика'
OLLAMA_INSTALL='/tmp/ollama-install.sh'
curl --proto '=https' --tlsv1.2 -fsSL https://ollama.com/install.sh -o "$OLLAMA_INSTALL"
chmod 700 "$OLLAMA_INSTALL"
sh "$OLLAMA_INSTALL"

install -d -m 0755 /etc/systemd/system/ollama.service.d
cat > /etc/systemd/system/ollama.service.d/auto-photo.conf <<'EOF'
[Service]
Environment="OLLAMA_HOST=127.0.0.1:11434"
Environment="OLLAMA_NUM_PARALLEL=1"
Environment="OLLAMA_MAX_LOADED_MODELS=1"
Environment="OLLAMA_KEEP_ALIVE=2m"
Environment="OLLAMA_CONTEXT_LENGTH=4096"
MemoryMax=5G
CPUQuota=300%
EOF
systemctl daemon-reload
systemctl enable --now ollama
systemctl restart ollama

for _ in $(seq 1 60); do
  if curl -fsS http://127.0.0.1:11434/api/version >/dev/null; then break; fi
  sleep 1
done
curl -fsS http://127.0.0.1:11434/api/version >/dev/null

echo '[4/7] Загружаю Qwen3-VL 2B (около 1.9 ГБ)'
ollama pull "$MODEL"

echo '[5/7] Обновляю модуль обработки фотографий до 0.4.0'
base64 -d > "$WHEEL" <<'WHEEL_BASE64'

WHEEL_BASE64
echo "$EXPECTED_SHA  $WHEEL" | sha256sum -c -
/opt/auto-photo-ingest/venv/bin/pip install --no-deps --force-reinstall "$WHEEL"
chmod -R a+rX /opt/auto-photo-ingest/venv

install -d -m 0755 /etc/systemd/system/auto-photo-ingest.service.d
cat > /etc/systemd/system/auto-photo-ingest.service.d/qwen.conf <<'EOF'
[Service]
Environment=VISION_PROVIDER=disabled
Environment=OLLAMA_URL=http://127.0.0.1:11434/api/chat
Environment=OLLAMA_MODEL=qwen3-vl:2b-instruct
EOF
systemctl daemon-reload

echo '[6/7] Проверяю модель на первых трёх автомобилях'
runuser -u auto-photo-ingest -- env OLLAMA_URL=http://127.0.0.1:11434/api/chat OLLAMA_MODEL="$MODEL" /opt/auto-photo-ingest/venv/bin/auto-photo-ingest screen-model --data-dir /var/lib/auto-photo-ingest --limit 3

echo '[7/7] Результаты тестовых трёх групп'
/opt/auto-photo-ingest/venv/bin/python - <<'PY'
import sqlite3
db = sqlite3.connect('/var/lib/auto-photo-ingest/catalogue.sqlite3')
db.row_factory = sqlite3.Row
rows = db.execute("SELECT id, plate_text, plate_confidence, condition_class, condition_notes, decision FROM vehicle_candidates WHERE decision <> 'pending_model' ORDER BY updated_at DESC LIMIT 3").fetchall()
for row in reversed(rows):
    print(dict(row))
db.close()
PY

echo
echo 'QWEN_TEST_READY'
echo 'Таймер оставлен остановленным до проверки качества этих трёх результатов.'
echo 'После подтверждения: sed -i s/VISION_PROVIDER=disabled/VISION_PROVIDER=ollama/ /etc/systemd/system/auto-photo-ingest.service.d/qwen.conf && systemctl daemon-reload && systemctl enable --now auto-photo-ingest.timer'
